from lib import *
S = SS('k23')
F1 = [['Pending', 'ContainerCreating'], ['Running', '容器已启动 +0.7s'], ['Ready=False', '就绪探针还没过'], ['Ready=True', '/tmp/ready 出现后']]
F2 = [['未调度', 'Pending + Unschedulable'], ['拉镜像中', 'Pending + ContainerCreating'], ['一次性成功', 'Succeeded'], ['一次性失败', 'Failed']]
