PANELS = [('f', 'flow', 'Pod 的状态层次'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod ok 带一个就绪探针(检查 /tmp/ready 是否存在):+0.0 秒 phase=Pending、容器 waiting(ContainerCreating),此时 PodScheduled 与 Initialized 已是 True,ContainersReady=False;+0.7 秒 phase=Running、容器 running,但 ContainersReady 和 Ready 仍是 False。在容器里创建 /tmp/ready 之后,Ready 与 ContainersReady 变成 True。Running 不等于 Ready。", f=fl(F1, cur=[1, 2], done=[0, 3]), t=tl(S(1), mark=lidx(S(1), 'phase=Pending', 'phase=Running'), done=lidx(S(1), '创建 /tmp/ready')), kv=KV([['phase', '粗粒度:Pending / Running / Succeeded / Failed'], ['conditions', 'PodScheduled → Initialized → ContainersReady → Ready'], ['容器 state', 'waiting / running / terminated']], ['conditions'])),
    step("四个 Pod 各卡在不同的位置:nosched(nodeSelector 无节点匹配)phase=Pending,PodScheduled=False reason=Unschedulable,message “0/3 nodes are available: …”;badimg(不存在的镜像标签)phase=Pending,容器 waiting(ContainerCreating);oneshot(restartPolicy=Never,echo hi)phase=Succeeded,容器 terminated(Completed,exitCode=0);failing(exit 3)phase=Failed,terminated(Error,exitCode=3)。kubectl get 的 STATUS 列是另一回事:ContainerCreating、Error、Pending、Running、Completed。", f=fl(F2, cur=[0, 1], done=[2], mark=[3]), t=tl(S(2), mark=lidx(S(2), 'nosched', 'badimg'), done=lidx(S(2), 'oneshot', 'failing')), kv=KV([['Pending', '未调度,或已调度但容器还没起来'], ['Succeeded / Failed', '只有 restartPolicy 不重启时才会出现'], ['STATUS 列', '是 kubectl 综合 phase、容器状态算出来的']], ['STATUS 列'])),
    step("Pod slow(sh -c \"sleep 3600\" 作为 1 号进程,不处理 SIGTERM,terminationGracePeriodSeconds=20)执行 kubectl delete 1 秒后:phase 仍是 Running,metadata.deletionTimestamp 已设置,deletionGracePeriodSeconds=20,容器 running;kubectl get 的 STATUS 列显示 Terminating。21 秒后进程被 SIGKILL,对象消失。", f=fl(F3, cur=[1, 2], done=[3]), t=tl(S(3), mark=lidx(S(3), 'phase=Running', 'Terminating'), done=lidx(S(3), '21 秒后')), kv=KV([['Terminating', '不是 phase,是 deletionTimestamp + kubectl 的展示'], ['不处理 SIGTERM', '要等满宽限期才被 SIGKILL'], ['deletionGracePeriodSeconds', '剩下的宽限期上限']], ['Terminating'])),
    step("restartPolicy=OnFailure、容器 3 秒后 exit 1 的 Pod flaky,30 秒后:phase=Running,restartCount=2,当前 state=terminated,lastState.terminated(exitCode=1,reason=Error);Ready=False(两次重启之间容器不就绪)。反复崩溃的 Pod 的 phase 一直是 Running,不会变成 Failed。", f=fl(F4, cur=[1], done=[2], mark=[3]), t=tl(S(4), mark=lidx(S(4), 'restartCount=2', 'Ready=False')), kv=KV([['重启', '发生在 Pod 内部,Pod 对象不变'], ['restartCount / lastState', '才是崩溃的记录'], ['phase', '不会因为崩溃变成 Failed']], ['restartCount / lastState'])),
]
A = mkartk('k23', 23, 'Kubernetes,Pod,phase,conditions,容器状态,Terminating,restartPolicy,真实验证,动画演示',
    '在 kind 集群里实测 Pod 的三层状态:phase、conditions、容器 state。就绪探针未通过时 phase=Running 而 Ready=False;未调度的 Pod phase=Pending 且 PodScheduled=False(Unschedulable);restartPolicy=Never 的一次性 Pod 成功是 Succeeded、失败是 Failed;删除时 phase 仍是 Running,Terminating 来自 deletionTimestamp,不处理 SIGTERM 的进程要等满宽限期(21 秒)才被杀;OnFailure 下反复崩溃的 Pod phase 一直是 Running,崩溃记录在 restartCount 与 lastState 里。',
    'kubectl get pod 的 STATUS 一栏、Pod 的 phase、conditions、容器 state,到底谁是谁?为什么 Running 的 Pod 还没就绪、为什么 Terminating 在 phase 里找不到?这篇用几个故意卡在不同位置的 Pod,把三层状态各自在什么时候变、和 kubectl 的显示怎么对应都量出来。',
    [('+0.0s → +0.7s', 'Pod ok 从 Pending 到 Running 的时间;Ready 还要等就绪探针通过'), ('Running + Ready=False', '就绪探针未通过时 Pod 的 phase 与 Ready 条件'), ('Terminating 不是 phase', '删除一个不响应 SIGTERM 的 Pod:phase 仍是 Running,21 秒后才消失')],
    [('Running 不等于 Ready', '<p>带就绪探针的 Pod 启动过程:+0.0 秒 <code>phase=Pending</code>(容器 <code>ContainerCreating</code>),这时 <code>PodScheduled</code>、<code>Initialized</code> 已经是 True;+0.7 秒 <code>phase=Running</code>,容器已经启动,但 <code>ContainersReady</code> 和 <code>Ready</code> 仍是 False,因为探针检查的 <code>/tmp/ready</code> 还不存在。创建这个文件之后 <code>Ready</code> 才变成 True。Service 只会把 <code>Ready</code> 的 Pod 加入后端,所以“Running”并不意味着能收流量。</p>'),
     ('卡在不同位置的 Pod', '<p>nodeSelector 无节点匹配的 Pod:<code>phase=Pending</code>,<code>PodScheduled=False</code>,reason <code>Unschedulable</code>,message <code>0/3 nodes are available: …</code>;镜像标签不存在的 Pod:<code>phase=Pending</code>,容器 <code>waiting(ContainerCreating)</code>——这台机器拉不到镜像,将近一分钟后还没有走到 ErrImagePull;<code>restartPolicy: Never</code> 的 echo 成功是 <code>Succeeded</code>,exit 3 是 <code>Failed</code>(容器 <code>terminated(Error)</code>、<code>exitCode=3</code>)。<code>kubectl get</code> 的 STATUS 列(ContainerCreating、Error、Completed……)是 kubectl 综合 phase 和容器状态算出来的,不是 phase。</p>'),
     ('Terminating', '<p>删除一个不处理 SIGTERM 的 Pod(<code>sh -c "sleep 3600"</code> 作 1 号进程):1 秒后 <code>phase</code> 仍是 <code>Running</code>,<code>metadata.deletionTimestamp</code> 已设置,<code>deletionGracePeriodSeconds=20</code>,容器还在运行,<code>kubectl get</code> 显示 <code>Terminating</code>。要等满 20 秒的宽限期,进程被 SIGKILL,Pod 对象才消失(这次 21 秒)。<code>Terminating</code> 是展示层的说法,不是 phase 的取值。</p>'),
     ('重启不改变 phase', '<p><code>restartPolicy: OnFailure</code>、3 秒后 <code>exit 1</code> 的容器,30 秒内重启了 2 次:<code>restartCount=2</code>,当前 <code>state=terminated</code>,<code>lastState.terminated</code> 记着上一次的 <code>exitCode=1</code>、<code>reason=Error</code>;<code>Ready=False</code>(两次重启之间容器不就绪),<code>phase</code> 却一直是 <code>Running</code>。反复崩溃的 Pod 不会变成 <code>Failed</code>,看崩溃要看 <code>restartCount</code> 和 <code>lastState</code>。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);Pod 状态每 0.25 秒用 kubectl get pod -o json 读一次并记录变化;ok 的就绪探针是 exec 检查 /tmp/ready,periodSeconds=1;busybox:1.36 已预先加载进节点,所以 ok 的启动只用了不到 1 秒;badimg 用的镜像标签不存在,本机拉不到镜像,约 1 分钟时仍在 ContainerCreating;每种情形各一次',
     '没有验证:phase=Unknown(节点失联时);ImagePullBackOff / ErrImagePull 的状态切换(本机拉取失败太慢);init 容器、sidecar 对 conditions 的影响(后面有专门的文章);Pod 的 readinessGates 与 DisruptionTarget 等较新的 condition;kubectl get 计算 STATUS 列的完整规则;preStop 钩子对终止过程的影响'],
    'Pod 状态层次', PANELS)
